practice.solution:
package main

import (
	"fmt"
	"math"
)

func main() {
	fmt.Println("max int32:", math.MaxInt32)
	fmt.Println("min int32:", math.MinInt32)
	fmt.Println("max uint8:", math.MaxUint8)
	var level int32 = math.MaxInt32
	level++
	fmt.Println("level:", level)
}

